"""Offline ADB and length-prefixed plist exchange parsing.

The parsers here are pure wire-format validators: no packet is ever
transmitted. A parsed open signature identifies the negotiated device
state; any framing, length, checksum or decoding problem yields `None`
so the caller can treat the row as malformed open wire data.
"""
import io
import plistlib
import struct

ADB_CNXN = 0x4e584e43
ADB_AUTH = 0x48545541
ADB_CLSE = 0x45534c43
ADB_HEADER = 24
ADB_MAX_BODY = 65535

SYNC_MAX_FRAME = 65532
SYNC_KEYS = ('ProductVersion','ProductName')


def checksum(data):
    """ADB checksum: sum of body bytes modulo 2**32."""
    return sum(data)&0xffffffff


def send_connect():
    """Outbound CNXN packet certifying an ADB probe."""
    body=b'host::zgrab2'
    return struct.pack('<6I',ADB_CNXN,0x01000000,4096,len(body),
                       checksum(body),ADB_CNXN^0xffffffff)+body


def send_close():
    """Outbound CLSE packet certifying an ADB probe teardown."""
    return struct.pack('<6I',ADB_CLSE,0,0,0,0,ADB_CLSE^0xffffffff)


def adb_version(arg0):
    """CNXN version triple from arg0 bits 16-23, 8-15 and 0-7."""
    return f'{(arg0>>16)&255}.{(arg0>>8)&255}.{arg0&255}'


def read_adb_response(data):
    """Parse exactly one inbound ADB packet into its open signature."""
    if len(data)<ADB_HEADER:
        raise ValueError('short ADB header')
    command,arg0,arg1,length,check,magic=struct.unpack('<6I',data[:ADB_HEADER])
    if command^magic!=0xffffffff:
        raise ValueError('bad ADB header magic')
    if length>ADB_MAX_BODY:
        raise ValueError('ADB body too large')
    body=data[ADB_HEADER:]
    if len(body)!=length:
        raise ValueError('ADB body length mismatch')
    if checksum(body)!=check:
        raise ValueError('ADB checksum mismatch')
    if command==ADB_CNXN:
        return ('CNXN',adb_version(arg0),body.decode('utf-8'))
    if command==ADB_AUTH:
        return ('AUTH',arg0,arg1,bytes(body))
    raise ValueError('unsupported ADB command')


def plist_value_request(key):
    """Outbound length-prefixed usbmuxd GetValue request plist frame."""
    body=plistlib.dumps({'Key':key,'Label':'usbmuxd','ProtocolVersion':'2',
                         'Request':'GetValue'},fmt=plistlib.FMT_XML,sort_keys=False)
    if not 1<=len(body)<=SYNC_MAX_FRAME:
        raise ValueError('generated plist frame out of range')
    return struct.pack('>I',len(body))+body


def parse_value_frame(body,expected_key):
    """Parse one GetValue response plist body into its Value string."""
    value=plistlib.loads(body)
    if type(value) is not dict or set(value)!={'Key','Request','Value'}:
        raise ValueError('unexpected GetValue dictionary')
    if value['Key']!=expected_key or value['Request']!='GetValue':
        raise ValueError('unexpected GetValue key or request')
    text=value['Value']
    if type(text) is not str or not text:
        raise ValueError('unexpected GetValue value')
    return text


def parse_sync(data):
    """Parse exactly two length-prefixed GetValue response frames."""
    frames=[]
    at=0
    for _ in SYNC_KEYS:
        if at+4>len(data):
            raise ValueError('truncated sync frame header')
        size=int.from_bytes(data[at:at+4],'big')
        at+=4
        if size<1 or size>SYNC_MAX_FRAME:
            raise ValueError('invalid sync frame length')
        if at+size>len(data):
            raise ValueError('truncated sync frame body')
        frames.append(data[at:at+size])
        at+=size
    if at!=len(data):
        raise ValueError('trailing sync frame data')
    values=[]
    for body,key in zip(frames,SYNC_KEYS):
        values.append(parse_value_frame(body,key))
    return ('sync',values[0],values[1])


def signature(kind,data):
    """Parsed open signature for an application payload, or None."""
    try:
        if kind=='tcp':
            if data:
                raise ValueError('TCP payload must be empty')
            return ('tcp',)
        if kind=='adb':
            return read_adb_response(data)
        return parse_sync(data)
    except MemoryError:
        raise
    except Exception:
        return None


def probe_script(kind):
    """Base64 probe certificate arrays for one service kind."""
    import base64
    encode=lambda b:base64.b64encode(b).decode('ascii')
    if kind=='tcp':
        return [],[]
    if kind=='adb':
        return [encode(send_connect())],[encode(send_close())]
    return [encode(plist_value_request(key)) for key in SYNC_KEYS],[]
PYEOF
